// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface RoundStatusOut {
  frequency: "DailyWeekly" | "MonthlyQuarterly" | "StorageQuarterly";
  /** The establishment's interval (settings qa_round_daily_weekly_days, qa_round_monthly_quarterly_days) */
  interval_days: number;
  active_items: number;
  last_round_id: number | null;
  last_round_number: string | null;
  last_conducted_at: string | null;
  days_since: number | null;
  /** Never done, or the interval has passed since the last round */
  is_due: boolean;
}

export interface QaChecklistItemOut {
  item_id: number;
  code: string;
  frequency: "DailyWeekly" | "MonthlyQuarterly" | "StorageQuarterly";
  position: number;
  text: string;
  /** The manual's form and item it comes from; null for the establishment's own */
  source: string | null;
  is_active: boolean;
  row_version: number;
}

export interface QaChecklistItemIn {
  code: string;
  frequency: "DailyWeekly" | "MonthlyQuarterly" | "StorageQuarterly";
  /** Its place in the checklist (the seeded items use 1-28) */
  position: number;
  text: string;
}

export interface QaChecklistItemUpdateIn {
  text?: string | null;
  position?: number | null;
  /** False retires the item from the next rounds */
  is_active?: boolean | null;
  /** Optimistic concurrency: the row_version you loaded */
  expected_version?: number | null;
}

export interface RoundIn {
  frequency: "DailyWeekly" | "MonthlyQuarterly" | "StorageQuarterly";
  /** The date and time of the inspection, with timezone (not in the future) */
  conducted_at: string;
  /** Every active item of the frequency, once (GET /qa/checklist-items) */
  items: RoundAnswerIn[];
  general_remarks?: string | null;
}

export interface RoundAnswerIn {
  item_id: number;
  result: "Satisfactory" | "NeedsAttention" | "NotApplicable";
  /** Required when the result is NeedsAttention */
  observation?: string | null;
  recommendation?: string | null;
}

export interface RoundDetailOut {
  round_id: number;
  round_number: string;
  frequency: "DailyWeekly" | "MonthlyQuarterly" | "StorageQuarterly";
  conducted_at: string;
  general_remarks: string | null;
  conducted_by: number;
  conducted_by_name: string;
  signed_stamp: AuthorStampOut;
  created_at: string;
  /** Items marked NeedsAttention */
  findings: number;
  items: RoundItemOut[];
  actions: QualityActionOut[];
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

export interface RoundItemOut {
  item_id: number;
  code: string;
  position: number;
  text: string;
  result: "Satisfactory" | "NeedsAttention" | "NotApplicable";
  observation: string | null;
  recommendation: string | null;
}

/** A corrective or preventive action of the hospital's register (MSDS IMS 162, CQI 83, 107). */
export interface QualityActionOut {
  action_id: number;
  action_number: string;
  /** What found the need: a medical record review, an incident, a complaint, an infection control audit, a committee meeting, a mock drill, a mock PHC interview, a QA round, a patient's feedback */
  source: "RecordReview" | "Incident" | "Complaint" | "InfectionAudit" | "Meeting" | "Drill" | "MockInterview" | "QaRound" | "PatientFeedback";
  cycle_id: number | null;
  cycle_number: string | null;
  incident_id: number | null;
  incident_number: string | null;
  complaint_id: number | null;
  complaint_number: string | null;
  ipc_audit_id: number | null;
  audit_number: string | null;
  meeting_id: number | null;
  meeting_number: string | null;
  drill_id: number | null;
  drill_number: string | null;
  mock_interview_id: number | null;
  /** The mock PHC interview that found the gap (MIV-...) */
  interview_number: string | null;
  qa_round_id: number | null;
  /** The in-charge's QA round whose finding it addresses (QAR-...) */
  qa_round_number: string | null;
  feedback_id: number | null;
  /** The patient feedback it answers (FB-...) */
  feedback_number: string | null;
  /** The number of the review cycle, the incident, the complaint, the audit or the meeting */
  source_number: string;
  action_type: "Corrective" | "Preventive";
  description: string;
  /** A record review: the checklist item whose deficiencies it addresses */
  criterion_code: string | null;
  department_id: number | null;
  department_name: string | null;
  owner_user_id: number;
  owner_name: string;
  due_date: string;
  status: "Open" | "Done" | "Cancelled";
  /** Done: what was done (the evidence); Cancelled: why it was dropped */
  outcome_note: string | null;
  completed_at: string | null;
  completed_by_name: string | null;
  created_by: number;
  created_by_name: string;
  created_at: string;
  row_version: number;
  is_overdue: boolean;
}

export interface RoundOut {
  round_id: number;
  round_number: string;
  frequency: "DailyWeekly" | "MonthlyQuarterly" | "StorageQuarterly";
  conducted_at: string;
  general_remarks: string | null;
  conducted_by: number;
  conducted_by_name: string;
  signed_stamp: AuthorStampOut;
  created_at: string;
  /** Items marked NeedsAttention */
  findings: number;
}

/** A corrective or preventive action for its source (a record review, an incident). */
export interface QualityActionIn {
  action_type: "Corrective" | "Preventive";
  description: string;
  /** Who carries it out; they are notified and close it with the evidence (GET /staff/lookup → user_id; GET /quality/record-review/people, GET /facility/staff) */
  owner_user_id: number;
  due_date: string;
  /** The department (GET /admin/departments) */
  department_id?: number | null;
}

/** Someone who can review records (can_review) or own an action. */
export interface PersonOut {
  user_id: number;
  display_name: string;
  designation: string | null;
  department_name: string | null;
  staff_category: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting" | null;
  can_review: boolean;
  default_discipline: "Medical" | "Nursing" | "Pharmacy" | "Laboratory" | "Other";
}

export interface DepartmentOut {
  department_id: number;
  code: string;
  name: string;
  is_clinical: boolean;
  is_active: boolean;
  row_version: number;
}

/** Which checklist is due — GET /api/v1/qa/rounds/status (who may call: holders of qa.round.conduct or qa.checklist.manage or msds.view). */
export function status(): Promise<RoundStatusOut[]> {
  return api<RoundStatusOut[]>("GET", `/qa/rounds/status`, undefined);
}

/** The checklist's items — GET /api/v1/qa/checklist-items (who may call: holders of qa.round.conduct or qa.checklist.manage or msds.view). */
export function listItems(query?: { frequency?: "DailyWeekly" | "MonthlyQuarterly" | "StorageQuarterly" | null; include_inactive?: boolean }): Promise<QaChecklistItemOut[]> {
  return api<QaChecklistItemOut[]>("GET", withQuery(`/qa/checklist-items`, query), undefined);
}

/** Add the establishment's own checklist item — POST /api/v1/qa/checklist-items (who may call: holders of qa.checklist.manage). */
export function addItem(body: QaChecklistItemIn): Promise<QaChecklistItemOut> {
  return api<QaChecklistItemOut>("POST", `/qa/checklist-items`, body, { idempotent: true });
}

/** Reword, move or retire a checklist item — PATCH /api/v1/qa/checklist-items/{item_id} (who may call: holders of qa.checklist.manage). */
export function updateItem(item_id: number, body: QaChecklistItemUpdateIn): Promise<QaChecklistItemOut> {
  return api<QaChecklistItemOut>("PATCH", `/qa/checklist-items/${item_id}`, body);
}

/** Conduct and sign a round — POST /api/v1/qa/rounds (who may call: holders of qa.round.conduct). */
export function conduct(body: RoundIn): Promise<RoundDetailOut> {
  return api<RoundDetailOut>("POST", `/qa/rounds`, body, { idempotent: true });
}

/** The rounds conducted — GET /api/v1/qa/rounds (who may call: holders of qa.round.conduct or qa.checklist.manage or msds.view). */
export function listRounds(query?: { frequency?: "DailyWeekly" | "MonthlyQuarterly" | "StorageQuarterly" | null; date_from?: string | null; date_to?: string | null; limit?: number; before_id?: number | null }): Promise<RoundOut[]> {
  return api<RoundOut[]>("GET", withQuery(`/qa/rounds`, query), undefined);
}

/** One round — GET /api/v1/qa/rounds/{round_id} (who may call: holders of qa.round.conduct or qa.checklist.manage or msds.view). */
export function getRound(round_id: number): Promise<RoundDetailOut> {
  return api<RoundDetailOut>("GET", `/qa/rounds/${round_id}`, undefined);
}

/** The signed round (PDF) — GET /api/v1/qa/rounds/{round_id}/pdf (who may call: holders of qa.round.conduct or qa.checklist.manage or msds.view). */
export function roundPdf(round_id: number): Promise<unknown> {
  return api<unknown>("GET", `/qa/rounds/${round_id}/pdf`, undefined);
}

/** Raise a corrective or preventive action from a round — POST /api/v1/qa/rounds/{round_id}/actions (who may call: holders of qa.round.conduct). */
export function addActionQaRoundsActions(round_id: number, body: QualityActionIn): Promise<QualityActionOut> {
  return api<QualityActionOut>("POST", `/qa/rounds/${round_id}/actions`, body, { idempotent: true });
}

/** Who can review records or own an action — GET /api/v1/quality/record-review/people (who may call: holders of quality.review.manage or committee.manage or infection.control.manage). */
export function people(): Promise<PersonOut[]> {
  return api<PersonOut[]>("GET", `/quality/record-review/people`, undefined);
}

/** Departments — GET /api/v1/admin/departments (who may call: any logged-in user). */
export function departments(): Promise<DepartmentOut[]> {
  return api<DepartmentOut[]>("GET", `/admin/departments`, undefined);
}
